contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(bool asOwner) public payable {
        uint balBefore = address(c).balance;
        address owner = c.Owner(); if (__ESBMC_reverted()) return;
        require((asOwner && owner == address(this)) || (!asOwner && owner != address(this)));

        bool reverted;
        c.withdraw(); bool __rev0 = __ESBMC_reverted(); if (__rev0) { reverted = true; } else { reverted = false; }

        uint balAfter = address(c).balance;
        assert(asOwner == !reverted && (asOwner ? balAfter == 0 : balAfter == balBefore));
    }

    receive() external payable {}
}

